    <qtimetadata>
        <qtimetadatafield>
          <fieldlabel>bank_title</fieldlabel>
          <fieldentry>CheckIt {{bankSlug}} {{slug}} (Build {{id}}) ({{questionType}}) | {{bank}}: {{title}}</fieldentry>
        </qtimetadatafield>
    </qtimetadata>
